<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script id="rampart-strategy">
function createStrategy(){
  const order=[2,7,4,11,6,8,1,13,3,5,9,12,0,10,14,15];
  const guns=['"'cannon','bolt','cannon','cannon','cannon','flak','cannon','cannon','cannon','cannon','cannon','cannon','cannon','cannon','flak','flak'];
  return {
    plan(s){
      let gold=s.gold; const actions=[];
      const costs={cannon:90,bolt:50,flak:80};
      const options=[];
      order.forEach((slot,i)=>{
        const t=s.slots[slot].turret,type=guns[i],tier=t?t.tier:0;
        if(tier<3)options.push({slot,type,tier,cost:costs[type]*Math.max(1,tier),priority:i*(tier?0.65:1)+[0,3,7][tier]});
      });
      options.sort((a,b)=>a.priority-b.priority);
      for(const o of options)if(gold>=o.cost){actions.push({op:o.tier?'upgrade':'build',slot:o.slot,type:o.type});gold-=o.cost;}
      return actions;
    },
    target(t,c){
      const splash=t.type==='cannon'?90:t.type==='flak'?70:0;
      let best=-Infinity,id=0;
      for(const e of c){
        let value=0;
        if(splash)for(const n of c)if((e.x-n.x)**2+(e.y-n.y)**2<=splash*splash)value+=1+(n.type==='mender'?0.7:0);
        const rank=value*(1+0.35*(1-e.remaining/4600))+0.45*(1-e.remaining/4600)+(e.air&&t.type==='bolt'?4:0)-0.00001*e.hp;
        if(rank>best){best=rank;id=e.id;}
      }return id;
    }
  };
}
</script>
<script id=\"rampart-sim\">
function rampartSimulate(createStrategy,seed,maxTicks){
  const record=arguments[3], strat=createStrategy(),floor=Math.floor;
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a "'^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0; }; }
  const random=mulberry32(seed);
  const types=['"'grunt','runner','wisp','brute','splitter','mender','splitling'];
  const hp=[60,40,50,150,90,70],speed=[10,20,12,6,8,8,12],bounty=[4,4,6,9,6,7,1],leak=[1,1,2,3,2,2,1],weights=[10,4,3,3,2,1],first=[1,2,3,4,6,8];
  const guns=['bolt','cannon','frost','lance','flak'],cost=[50,90,70,120,80],power=[26,60,10,180,40],period=[8,24,12,36,10],range=[300,260,240,360,320],radius=[0,90,0,0,70];
  const slots=[[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]].map(([x,y],slot)=>({x:x*100+50,y:y*100+50,slot,turret:null}));
  const routes=[[[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],[[0,6],[21,6],[21,11],[23,11]]];
  const lengths=[4600,2600],mult=[0,1000],queue=new Map(),log=[];
  let enemies=[],gold=250,baseHp=10,tick=0,wave=0,fallTick=-1,lastId=0,events=[];
  function gen(w){
    const n=first.filter(v=>v<=w).length,sum=weights.slice(0,n).reduce((a,b)=>a+b,0);
    return Array.from({length:4+floor(3*w/5)},()=>{let r=random()%sum,i=0;while(r>=weights[i])r-=weights[i++];return i;});
  }
  let next=gen(1);
  function fx(kind,x,y,data={}){if(record)events.push({kind,x:x/100,z:y/100,...data});}
  function place(e){
    let p=e.progress;const path=routes[e.air];
    for(let i=1;i<path.length;i++){
      const [x,y]=path[i-1],[u,v]=path[i],dx=Math.sign(u-x),dy=Math.sign(v-y),len=(Math.abs(u-x)+Math.abs(v-y))*100;
      if(p<=len||i===path.length-1){e.x=x*100+50+p*dx;e.y=y*100+50+p*dy;e.dir=Math.atan2(dx,dy);break;}p-=len;
    }e.remaining=lengths[e.air]-e.progress;
  }
  function spawn(i,w,p=0,maxHp=floor(hp[i]*mult[w]/1000)){
    const e={id:++lastId,i,type:types[i],wave:w,progress:p,air:+(i===2),maxHp,hp:maxHp,armor:i===0?floor(w/4):i===3?6+w:0,speed:speed[i],slowed:0,age:0};place(e);enemies.push(e);
  }
  function view({id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining}){return {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining};}
  function slotView(s){const t=s.turret;return {...s,turret:t?{type:t.type,tier:t.tier,spent:t.spent}:null};}
  function snapshot(){if(record)record({tick,wave,gold,baseHp,next:next.map(i=>types[i]),slots:slots.map(slotView),enemies:enemies.map(e=>({...view(e),dir:e.dir})),events});}
  function dist(a,b){return (a.x-b.x)**2+(a.y-b.y)**2;}
  for(;tick<maxTicks;tick++){
    events=[];
    if(tick>=20&&(tick-20)%40===0){
      wave++;gold+=Math.min(50,floor(gold*5/100))+10+2*wave;
      if(wave>1)mult[wave]=floor(mult[wave-1]*108/100);
      const current=next;next=gen(wave+1);fx('wave',50,250);
      const actions=strat.plan({tick,wave,gold,baseHp,slots:slots.map(slotView),enemies:enemies.map(view),nextWave:next.map(i=>types[i])});
      for(const a of (Array.isArray(actions)?actions:[]).slice(0,32)){
        if("'!a||!Number.isInteger(a.slot)||!slots[a.slot])continue;
        const s=slots[a.slot],t=s.turret,i=guns.indexOf(a.type);
        if(a.op==='"'build'&&"'!t&&i>=0&&gold>=cost[i]){s.turret={type:guns[i],i,tier:1,spent:cost[i],cd:0,d:power[i]};gold-=cost[i];log.push([tick,'"'B',s.slot,i]);}
        else if(a.op==='upgrade'&&t&&t.tier<3&&gold>=cost[t.i]*t.tier){const pay=cost[t.i]*t.tier;gold-=pay;t.spent+=pay;t.tier++;t.d=floor(t.d*16/10);log.push([tick,'U',s.slot,t.tier]);}
        else if(a.op==='sell'&&t){gold+=floor(t.spent*7/10);s.turret=null;log.push([tick,'S',s.slot,0]);}else continue;
        fx(a.op,s.x,s.y);
      }
      current.forEach((i,j)=>{const due=tick+j*4;if("'!queue.has(due))queue.set(due,[]);queue.get(due).push([i,wave]);});
    }
    for(const a of queue.get(tick)||[])spawn(...a);queue.delete(tick);
    for(const e of enemies){
      e.progress+=e.slowed?floor(e.speed*60/100):e.speed;place(e);
      if(e.remaining<=0){baseHp-=leak[e.i];e.gone=true;log.push([tick,'"'L',e.id,baseHp]);fx('leak',2350,1150);if(baseHp<=0){fallTick=tick;log.push([tick,'F',wave,0]);fx('fall',2350,1150);break;}}
    }
    enemies=enemies.filter(e=>"'!e.gone);
    if(fallTick>=0){snapshot();break;}
    for(const e of enemies)if(++e.age%20===0&&e.i===5){fx('"'heal',e.x,e.y);for(const n of enemies)if(dist(e,n)<=22500)n.hp=Math.min(n.maxHp,n.hp+floor(n.maxHp*8/100));}
    for(const s of slots){
      const t=s.turret;if("'!t||t.cd>0&&--t.cd>0)continue;
      const i=t.i,r=range[i]+30*(t.tier-1),domain=e=>e.air?i!==1&&i!==3:i!==4;
      const c=enemies.filter(e=>domain(e)&&dist(s,e)<=r*r);if(!c.length)continue;
      const id=strat.target?.({slot:s.slot,type:t.type,tier:t.tier,x:s.x,y:s.y,range:r},c.map(view));
      const target=c.find(e=>e.id===id)||c.reduce((a,b)=>b.remaining<a.remaining?b:a);
      fx('"'shot',s.x,s.y,{gun:t.type,tx:target.x/100,tz:target.y/100,air:target.air,slot:s.slot});
      for(const e of radius[i]?enemies.filter(e=>domain(e)&&dist(e,target)<=radius[i]**2):[target]){
        e.hp-=Math.max(1,t.d-(i===3?0:e.armor));if(i===2)e.slowed=30;
      }t.cd=period[i];
      const dead=enemies.filter(e=>e.hp<=0);
      if(dead.length){enemies=enemies.filter(e=>e.hp>0);for(const e of dead){gold+=bounty[e.i];log.push([tick,'K',e.id,s.slot]);fx('kill',e.x,e.y,{type:e.type,air:e.air});if(e.i===4)for(let j=0;j<3;j++)spawn(6,e.wave,e.progress,Math.max(1,floor(e.maxHp/4)));}}
    }
    for(const e of enemies)if(e.slowed)e.slowed--;
    snapshot();
  }
  let h=0x811c9dc5;const str=JSON.stringify(log);for(let j=0;j<str.length;j++)h=Math.imul(h"'^str.charCodeAt(j),0x01000193);
  return {score:Math.round((tick-20)/40*100)/100,fallTick,log,hash:(h>>>0).toString(16).padStart(8,'"'0')};
}
</script>
