sed -i '' '/data-speed=\"false\"/d' index.html
cat >/tmp/ramp-test.py <<'PY'
import re,subprocess
s=open('index.html').read()
js='\\n'.join(re.findall(r'<script id=\"["'^"]+">(['"\\s\\S]*?)</script>',s))
vec=\"\"\"const A=()=>({plan(s){let a=[],g=s.gold;for(let sl of s.slots)if("'!sl.turret&&g>=50){a.push({op:'"'build',slot:sl.slot,type:'bolt'});g-=50;}return a;}}), B=()=>({plan(s){return ({1:[{op:'build',slot:3,type:'cannon'},{op:'build',slot:6,type:'frost'}],3:[{op:'upgrade',slot:3},{op:'build',slot:12,type:'flak'}],6:[{op:'build',slot:8,type:'lance'},{op:'sell',slot:6}]})[s.wave]||[];}});
for(const [st,seed] of [[A,42],[B,7],...[1,2,3,4,5,42].map(i=>[createStrategy,i])]){let r=rampartSimulate(st,seed,12020);print(seed,r.score,r.fallTick,r.hash,r.log.length);}
\"\"\"
open('/tmp/ramp-test.js','w').write(js+vec)
subprocess.run(['/System/Library/Frameworks/JavaScriptCore.framework/Versions/A/Helpers/jsc','/tmp/ramp-test.js'])
PY
python3 /tmp/ramp-test.py"

